  });
  const raw = await jobResponse.text();
  if (!jobResponse.ok && jobResponse.status !== 202) {
    throw new Error(`runner ${actionConfig.action} failed: ${jobResponse.status} ${raw}`);
  }
  dispatchResult = raw ? JSON.parse(raw) : null;
}
return [{ json: { ok: true, githubEvent, action, route, prNumber, reportRelativePath, dispatchResult, webhookBase } }];
